    try { static_cast<void>(proxy.refresh()); }
    catch (const std::runtime_error&) { refresh_denied = true; }
    check(refresh_denied && source.reads == 4);
    source.hour = 11;
    proxy.allow(true);
    check(proxy.opening() == 10 && source.reads == 4);
