};

void run_checks() {
    rejects([] { Monitor absent(nullptr); });
    rejects([] { AtLeast invalid(126.0); });
    Monitor m(std::make_unique<AtLeast>(80.0));
    rejects([&] { m.ingest({{1, 20.0, 'C'}}); });
    rejects([&] { m.resume(); });
    rejects([&] { m.stop(); });
    check(m.state() == State::idle, "invalid transition changed state");
    m.start();
