struct Job {
    std::string format;
    int pages;
};
using Reply = std::optional<std::string>;
using Rule = std::function<Reply(const Job&)>;

Reply label_rule(const Job& job) {
    // No value means keep looking.
    if (job.format != "label") {
        return std::nullopt;
